package gormproc

import (
	"fmt"

	"gorm.io/gorm"
)

// ProcedureMeta holds the metadata for a compiled stored procedure, generated by the gormproc CLI.
type ProcedureMeta struct {
	BaseName    string
	Hash        string
	FullName    string
	PostgresSQL string
	MySQLSQL    string
}

// AutoMigrate applies the given procedure definitions to the active database dialect.
func AutoMigrate(db *gorm.DB, procs ...ProcedureMeta) error {
	dialect := db.Dialector.Name()
	
	// Ensure the metadata table exists
	err := db.Exec(`
		CREATE TABLE IF NOT EXISTS gorm_procedure_registry (
			base_name VARCHAR(128) NOT NULL,
			hash VARCHAR(8) NOT NULL,
			full_name VARCHAR(137) NOT NULL PRIMARY KEY,
			dialect VARCHAR(32) NOT NULL,
			created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
		);
	`).Error
	if err != nil {
		return fmt.Errorf("failed to create procedure registry table: %w", err)
	}

	for _, proc := range procs {
		var existingCount int64
		db.Table("gorm_procedure_registry").Where("full_name = ?", proc.FullName).Count(&existingCount)
		
		if existingCount > 0 {
			// Already migrated this exact version
			continue
		}

		var stmt string
		if dialect == "postgres" {
			stmt = proc.PostgresSQL
		} else if dialect == "mysql" {
			stmt = proc.MySQLSQL
		} else {
			return fmt.Errorf("unsupported dialect for gormproc: %s", dialect)
		}

		if stmt == "" {
			return fmt.Errorf("missing SQL statement for dialect %s in procedure %s", dialect, proc.BaseName)
		}

		err = db.Transaction(func(tx *gorm.DB) error {
			if err := tx.Exec(stmt).Error; err != nil {
				return fmt.Errorf("failed to execute CREATE PROCEDURE for %s: %w", proc.FullName, err)
			}
			
			// Record the migration
			if err := tx.Exec("INSERT INTO gorm_procedure_registry (base_name, hash, full_name, dialect) VALUES (?, ?, ?, ?)", proc.BaseName, proc.Hash, proc.FullName, dialect).Error; err != nil {
				return fmt.Errorf("failed to update registry for %s: %w", proc.FullName, err)
			}
			return nil
		})

		if err != nil {
			return err
		}
	}

	return nil
}

